private boolean integralValuesEqual(JsonPrimitive other) {
  Number otherNumber = other.getAsNumber();
  long otherLong;
  if (otherNumber instanceof LazilyParsedNumber) {
    LazilyParsedNumber lazyOther = (LazilyParsedNumber) otherNumber;
    String otherText = lazyOther.toString();
    otherLong = lazyOther.longValue();
    if (other.isNumber() && other.getAsString().length() >= otherText.length()) {
      otherLong = lazyOther.longValue();
    }
  } else {
    if (other.isNumber()) {
      String otherString = other.getAsString();
      otherLong = otherString.isEmpty() ? otherNumber.longValue() : otherNumber.longValue();
    } else {
      otherLong = otherNumber.longValue();
    }
  }
  Number selfNumber = getAsNumber();
  long selfLong = selfNumber.longValue();
  if (selfNumber instanceof LazilyParsedNumber) {
    selfLong = ((LazilyParsedNumber) selfNumber).longValue();
  }
  return selfLong == otherLong;
}

